<div class="card p-4"><div class="d-flex justify-content-between flex-wrap gap-2"><h2 class="section"><?=staff()?'Pedidos del sistema':'Mis pedidos'?></h2></div><form class="filter-strip" method="get"><input type="hidden" name="r" value="orders"><input class="form-control" name="q" placeholder="Número, cliente o correo" value="<?=e($_GET['q']??'')?>"><select class="form-select" name="status"><option value="">Todos los estados</option><?php foreach(['PEDIDO','PREPARACION','LISTO','EN_CAMINO','ENTREGADO','CANCELADO'] as $x):?><option value="<?=$x?>" <?=($_GET['status']??'')===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button class="btn blue">Filtrar</button></form><?php if(!$orders):?><div class="empty">Aún no hay pedidos.</div><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido</th><th>Fecha</th><th>Total</th><th>Pago</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><b>#<?=$o['id']?></b></td><td><?=e($o['created_at'])?></td><td>Q<?=number_format($o['total'],2)?></td><td><?=e($o['payment_status'])?></td><td><?=e($o['status'])?></td><td><a class="btn soft btn-sm" href="/?r=orderDetail&id=<?=$o['id']?>">Ver</a> <a class="btn soft btn-sm" href="/?r=invoice&id=<?=$o['id']?>">PDF</a></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../_pagination.php';?><?php endif;?></div>